return {rw01={id="rw01",baseId="rwnpc01",combatid={1,1001},name="王庚金",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL王庚金：萍水相逢便是缘，近日这附近不太平，少侠可要小心。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：最近渡口可不太平，少侠多留个心眼。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",0}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={{type="inroom",args={"hdroom1803","hdroom1804"}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw02={id="rw02",baseId="rwnpc02",combatid={2,100033},name="混混",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL混混：看什么看，走你的路去。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL混混：多管闲事的家伙。NOR"}}},caozuoName3="制服",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="challenge",args={"rw02"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",1}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={{type="challengewin",args={"rw02"}}}},autoResult2={{type="gaintab",args={"318001",2}},{type="doc",args={"CYN那混混见打不过你，赶忙往渡口里跑了。NOR"}},{type="outobject",args={"rw02"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw03={id="rw03",baseId="rwnpc03",combatid={2,100033},name="混混头子",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"CYN那几人眼神不善的看着你。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL混混头子：就是你打了老四？拂了我的面子，这得说道说道吧？NOR"}},{type="doc",args={"YEL混混头子：是想交钱了事啊，还是说想尝尝我们几个的手段？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}},{type="showbutton",args={4,1}}},caozuoName2="教训一二",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"CYN你抬手稳稳扣住那人打向你的手腕，将其制住。混混挣脱不开，赶忙使着眼色要其他人帮忙。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"CYN你手上用力一翻，向前一推，几人倒在一边，站起身后又向你攻来。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="challenge",args={"rw03"}}},caozuoName3="下狠手",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"CYN你直接出手打向离你最近的那个混混。那人躲闪不及被直接打中胸口，一口鲜血吐出，仰倒下去。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"CYN后面几个混混哪见过这场面，愣在原地，他们身后的老大直接把他们推上前，抄起武器向你打来。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="challenge",args={"rw07"}}},caozuoName4="给钱了事",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"CYN你见他们围上来，故作惊慌，连道数声误会，为首那人却得寸进尺，上来就要搜你的身。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"CYN你往旁边一躲，脚下使个绊子。其他几个混混见状要围上来揍你，你不愿出手，只是绕着摊子转圈，嘴里嚷嚷着救命啊抢钱啦。NOR"}},{type="delayer",args={2,"少侠稍安勿躁！"}},{type="doc",args={"CYN这时一个少年站了出来拦住了他们，手上刀没出鞘，用刀鞘把那几个混混打的抱头鼠窜，混混见你还有帮手，一时间讨不到好处，便骂骂咧咧的离开了。NOR"}},{type="gaintab",args={"318001",3}},{type="gaintab",args={"318004",1}},{type="change",args={"rw01","rw06"}},{type="outobject",args={"rw02"}},{type="outobject",args={"rw03"}},{type="outobject",args={"rw07"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengewin",args={"rw03"}},{type="equaltab",args={"318001",2}}}},autoResult1={{type="gaintab",args={"318001",3}},{type="gaintab",args={"318002",1}},{type="doc",args={"CYN有个混混倒在地上还想偷袭，一旁的少年看到直接举起刀鞘将他打昏过去，对你拱了拱手。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：少侠好功夫，替天行道，伸张正义。在下王庚金，想与少侠交个朋友。NOR"}},{type="outobject",args={"rw02"}},{type="outobject",args={"rw03"}},{type="outobject",args={"rw07"}},{type="change",args={"rw01","rw04"}},{type="refresh",args={}}},autoCondition2={relation="and",conditions={{type="challengewin",args={"rw07"}},{type="equaltab",args={"318001",2}}}},autoResult2={{type="gaintab",args={"318001",3}},{type="gaintab",args={"318003",1}},{type="doc",args={"CYN混混都被打倒在地，发出阵阵呻吟，身上或多或少沾着些血迹。周围的人连忙退开，像避瘟神一样避着你，唯有一个少年眼放亮光，口中叫好，从人群中走出。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：打得好！这帮混混天天在这附近作威作福，就该狠狠教训他们长个记性。在下王庚金，少侠如此豪爽，在下想与少侠交个朋友。NOR"}},{type="outobject",args={"rw02"}},{type="outobject",args={"rw03"}},{type="outobject",args={"rw07"}},{type="change",args={"rw01","rw05"}},{type="refresh",args={}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw04={id="rw04",baseId="rwnpc01",combatid={1,1001},name="王庚金",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL王庚金：这帮混子欺软怕硬，腿脚倒是利索。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：得快些找个能躲雪的地方。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL王庚金：我看这旁边有个窝棚，我们快些过去。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL王庚金：少侠没事吧？嘶，我这还好，一点小伤而已，得劳烦少侠帮忙涂个药了。NOR"}},{type="showbutton",args={5,1}}},caozuoName5="涂药",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"CYN你接过药，帮他涂上，他一时间痛的龇牙咧嘴的，想叫又碍着面子不好叫出声来。NOR"}},{type="gaintab",args={"318002",5}},{type="showbutton",args={4,0}},{type="showbutton",args={5,0}},{type="showbutton",args={6,1}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"CYN外面雪下的太大，在这窝棚里也没啥消遣，王庚金自顾自的开始聊起他在镖局的一些趣事。什么送镖时的奇遇啊，在镖局里的热闹啊，想到什么就说什么。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"CYN聊着聊着，外面的雪渐渐小了，看样子能出发了。NOR"}},{type="gaintab",args={"318002",6}},{type="change",args={"rw04","rw08"}},{type="refresh",args={}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"318007",0}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318002",1}},{type="inroom",args={"hdroom1806","hdroom1807"}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"318002",2}},{type="inroom",args={"hdroom1807","hdroom1808"}}}},autoResult3={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"318002",3}},{type="inroom",args={"hdroom1808","hdroom1812"}}}},autoResult4={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition5={relation="and",conditions={{type="inroom",args={"any","hdroom1813"}}}},autoResult5={{type="showbutton",args={2,0}}},autoCondition6={relation="and",conditions={}},autoResult6={}},rw05={id="rw05",baseId="rwnpc01",combatid={1,1001},name="王庚金",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL王庚金：少侠好身手，对这种人就该狠狠地教训他们一次。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：雪太大了，这样走下去要在山里迷路的，先找个地方歇一歇吧。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL王庚金：这帮畜生也就会干这些腌臜事，少侠可有受伤？我这还有些不错的伤药。NOR"}}},caozuoName4="歇息一会",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL王庚金：少侠近段时间没来小镇，可能不知。最近小镇附近实在是有些乱，又是难民又是土匪，护镖也难了许多。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：这段时间出来，在路上还是要多加小心，后院还有好些货物，估计这帮劫匪就是跟着这商队一路过来的，杀人越货，刚好被我们撞上了，唉。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"CYN王庚金见气氛有些僵，又聊起了自己送镖的事，过了一会，外面的雪慢慢停了。NOR"}},{type="gaintab",args={"318003",5}},{type="refresh",args={}},{type="showbutton",args={3,0}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL王庚金：得快些走，晚了这雪可能又要下起来了。NOR"}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"YEL王庚金：少侠实力高强，实不相瞒，刚刚我与周掌柜交谈，这次的镖只怕不简单，背后估计有不少人盯着这趟镖。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：本地的镖头不知去了哪里，来之前就没他的消息，这周掌柜现在也支支吾吾，我心里实在没个打底。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：我愿出此次送镖报酬的三成给少侠，只求少侠愿意一同走一趟镖，最多一天时间，拜托少侠了。NOR"}},{type="gaintab",args={"318001",9}},{type="delayer",args={3,"少侠稍安勿躁！"}},{type="outgame",args={"hdfb1801"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"318007",0}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318003",1}},{type="inroom",args={"hdroom1808","hdroom1809"}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"318003",4}}}},autoResult3={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={{type="inroom",args={"hdroom1824","hdroom1825"}}}},autoResult4={{type="showbutton",args={5,0}},{type="showbutton",args={6,1}}},autoCondition5={relation="and",conditions={{type="inroom",args={"hdroom1809","hdroom1813"}}}},autoResult5={{type="showbutton",args={2,0}}},autoCondition6={relation="and",conditions={}},autoResult6={}},rw06={id="rw06",baseId="rwnpc01",combatid={1,1001},name="王庚金",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL王庚金：少侠动作敏捷，机敏过人，在下王庚金，想与少侠交个朋友，不知少侠过渡口是要去往何处？实不相瞒，最近这附近匪患闹得厉害，若是同路倒也有个照应。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：正巧，我此行是要去小镇接镖，少侠若不嫌弃，不如一道同行？就当是帮我个忙，放心，一路上绝不用你动手，我来解决那些胡搅蛮缠的家伙。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：这路我走过好多回了，一路过去就能到小镇。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL王庚金：雪太大了，这附近我记得有地方避风，先找个地方歇一歇吧。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL王庚金：少侠小心些，这帮和尚看着奇怪，不像是好人。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL王庚金：这几个和尚动作有些奇怪，只怕是图谋不轨，一直想让我们到后院去。不如这样，我往后院走，少侠到庙内盯着他们，若有异常，直接提醒我就是，我们一前一后一起把他们制服。NOR"}},{type="showbutton",args={4,0}},{type="showbutton",args={5,0}},{type="showbutton",args={6,1}},{type="gaintab",args={"318004",4}}},caozuoName6="动手",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"CYN王庚金正往内堂走，那两个和尚便开始蠢蠢欲动，手上好像拿着匕首要向他背后刺去。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"CYN你一脚踹到后面那个和尚背上，那和尚一个踉跄栽倒在地。你大吼一声衙门的人来了，另一个和尚还正愣神，王庚金已经回头将他扭住，压在地上。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"CYN那两人还不死心，叫骂着说你们是土匪强盗，来抢这荒庙来了。王庚金从他二人身手摸出匕首扔在一边，将二人绑好。NOR"}},{type="change",args={"rw06","rw13"}},{type="gaintab",args={"318004",5}},{type="refresh",args={}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"318007",0}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318004",1}},{type="inroom",args={"hdroom1809","hdroom1810"}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"318004",2}},{type="inroom",args={"hdroom1810","hdroom1815"}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={5,1}}},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw07={id="rw07",baseId="rwnpc04",combatid={2,100033},name="混混",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL混混：看什么看，拂了大哥面子还想走？NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw08={id="rw08",baseId="rwnpc01",combatid={1,1001},name="王庚金",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL王庚金：少侠，是时候出发了。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：再走一会就要到了，到了小镇上，有啥事提我的名字，好使。NOR"}}},caozuoName3="询问",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL王庚金：少侠，只怕还有些事需要麻烦你了，刚刚我与周掌柜交谈，这次的镖只怕不简单，背后估计有不少人盯着这趟镖。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：本地的镖头不知去了哪里，来之前就没他的消息，这周掌柜现在也支支吾吾，我心里实在没个打底。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：就明天一天，不会耽搁多少时间，镖送到后三成报酬交由少侠，拜托少侠了。NOR"}},{type="gaintab",args={"318001",9}},{type="delayer",args={3,"少侠稍安勿躁！"}},{type="outgame",args={"hdfb1801"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",condit