pe="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：好好的寺庙，却成了他们的财路。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL王庚金：那两人便扔在那，晚些到了小镇，再叫官府的人来把他们押走。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL王庚金：少侠感知超凡，应该已经猜到，刚刚我与周掌柜交谈，这次的镖只怕不简单，背后估计有不少人盯着这趟镖。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：本地的镖头不知去了哪里，来之前就没他的消息，这周掌柜现在也支支吾吾，我心里实在没个打底。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：我愿出此次送镖报酬的三成给少侠，只求少侠愿意一同走一趟镖，帮忙出谋划策便好，以少侠的才智，想必能轻易找出异常，拜托少侠了。NOR"}},{type="gaintab",args={"318001",9}},{type="delayer",args={3,"少侠稍安勿躁！"}},{type="outgame",args={"hdfb1801"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"318007",0}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318004",7}},{type="inroom",args={"hdroom1815","hdroom1810"}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="inroom",args={"hdroom1824","hdroom1825"}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw14={id="rw14",baseId="rwnpc09",combatid={1,1001},name="周掌柜",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL周掌柜：客官来店里，是住店还是？NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow